  right: { tr: 'Sağ: öznenin sağ yanı (kamera öznenin sağında).', en: 'Right: the subject’s right side (camera at the subject’s right).' },
  top: { tr: 'Üst: yukarıdan görünüm — öznenin önü görselin altında.', en: 'Top: seen from above — the subject’s front at the image bottom.' },
  bottom: { tr: 'Alt: aşağıdan görünüm — öznenin önü görselin üstünde.', en: 'Bottom: seen from below — the subject’s front at the image top.' },
